    return api.orders.handle_create({"customer_id": customer_id,
                                     "items": [{"sku": s, "quantity": q} for s, q in items]})


def test_packing_slip_lists_lines_in_item_order_with_catalogue_names(shop):
    order_id = order(shop, "c2", ("PEN", 3), ("BOOK", 1)).body["order_id"]
    response = shop.fulfilment.handle_packing_slip(order_id)
    assert response.status == 200
    assert response.body == {
        "order_id": order_id,
        "customer_name": "Grace",
        "lines": [
            {"sku": "PEN", "name": "Pen", "quantity": 3},
            {"sku": "BOOK", "name": "Book", "quantity": 1},
        ],
    }


def test_packing_slip_unknown_order_is_404(shop):
    response = shop.fulfilment.handle_packing_slip("ord-9999")
    assert response.status == 404
    assert response.body == {"error": "order not found"}


def test_packing_slip_cancelled_order_is_409(shop):
    order_id = order(shop, "c1", ("BOOK", 1)).body["order_id"]
    shop.orders.handle_cancel(order_id)
    response = shop.fulfilment.handle_packing_slip(order_id)
    assert response.status == 409
    assert "error" in response.body


def test_low_stock_strictly_below_threshold_sorted_by_on_hand_then_sku(shop):
    # shop: BOOK=50, LAMP=5, PEN=100. Add a tie to check the SKU tie-break.
    shop.catalog.handle_add_product({"sku": "CUP", "name": "Cup", "unit_price_cents": 800, "on_hand": 5})
    shop.catalog.handle_add_product({"sku": "ALE", "name": "Ale", "unit_price_cents": 100, "on_hand": 2})
    response = shop.fulfilment.handle_low_stock(10)
    assert response.status == 200
    assert response.body == {"products": [
        {"sku": "ALE", "name": "Ale", "on_hand": 2},
        {"sku": "CUP", "name": "Cup", "on_hand": 5},
        {"sku": "LAMP", "name": "Lamp", "on_hand": 5},
    ]}


def test_low_stock_excludes_stock_equal_to_threshold(shop):
    # LAMP has exactly 5 on hand, so a threshold of 5 must not include it.
    assert shop.fulfilment.handle_low_stock(5).body == {"products": []}
    shop.catalog.handle_add_product({"sku": "OLD", "name": "Old", "unit_price_cents": 1, "on_hand": 0})
    assert shop.fulfilment.handle_low_stock(1).body == {"products": [
        {"sku": "OLD", "name": "Old", "on_hand": 0},
    ]}


def test_low_stock_rejects_bad_threshold(shop):
    for bad in (-1, True, False, 1.5, "3", None):
        response = shop.fulfilment.handle_low_stock(bad)
        assert response.status == 400
        assert "error" in response.body


def test_restock_adds_quantity_and_returns_new_level(shop):
    response = shop.fulfilment.handle_restock({"sku": "LAMP", "quantity": 10})
    assert response.status == 200
    assert response.body == {"sku": "LAMP", "on_hand": 15}
    assert shop.catalog.handle_get("LAMP").body["on_hand"] == 15


def test_restocked_units_are_orderable_immediately(shop):
    # LAMP starts with 5, so an order for 12 is refused until restocked.
    assert order(shop, "c1", ("LAMP", 12)).status == 409
    shop.fulfilment.handle_restock({"sku": "LAMP", "quantity": 10})
    assert order(shop, "c1", ("LAMP", 12)).status == 201


def test_restock_unknown_product_is_404_and_changes_nothing(shop):
    response = shop.fulfilment.handle_restock({"sku": "NOPE", "quantity": 3})
    assert response.status == 404
    assert response.body == {"error": "product not found"}


def test_restock_rejects_bad_input_without_change(shop):
    bad_requests = [
        {"sku": "", "quantity": 1},
        {"sku": 7, "quantity": 1},
        {"quantity": 1},
        {"sku": "LAMP", "quantity": 0},
        {"sku": "LAMP", "quantity": -2},
        {"sku": "LAMP", "quantity": True},
        {"sku": "LAMP", "quantity": 1.0},
        {"sku": "LAMP"},
    ]
    for bad in bad_requests:
        response = shop.fulfilment.handle_restock(bad)
        assert response.status == 400, bad
        assert "error" in response.body, bad
    assert shop.catalog.handle_get("LAMP").body["on_hand"] == 5


